    "txt-contact-206": "⚠️ Si vous êtes en situation d'urgence vitale, n'attendez pas. Appelez le <strong>15</strong> (SAMU), <strong>3114</strong> (suicide), <strong>3919</strong> (violences) ou <strong>115</strong> (hébergement).",
    "txt-contact-207": "<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-186\">🏥 SAMU — urgence médicale</span><strong>15</strong>\n</div>\n<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-187\">💙 Prévention suicide</span><strong>3114</strong>\n</div>\n<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-188\">🟣 Violences conjugales</span><strong>3919</strong>\n</div>\n<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-189\">🏠 Hébergement d'urgence</span><strong>115</strong>\n</div>\n<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-190\">🧒 Enfant en danger</span><strong>119</strong>\n</div>\n<div style=\"display:flex; justify-content:space-between; padding:10px; background:var(--light); border-radius:var(--radius-sm);\">\n<span data-i18n=\"txt-contact-191\">🚒 Pompiers</span><strong>18</strong>\n</div>",
