    "txt-humanitaire-365": "Personnes disparues",
    "txt-humanitaire-366": "<table>\n<thead>\n<tr><th>Domaine</th><th>Structure / Dispositif</th><th>Pour qui</th></tr>\n</thead>\n<tbody>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-310\">Emploi</span></td><td>France Travail (ex Pôle Emploi), Missions Locales, Cap Emploi</td><td>Demandeurs d'emploi, jeunes, personnes handicapées</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-humanitaire-311\">Formation</span></td><td>CPF (Mon Compte Formation), OPCO, Pôle Emploi, AFPA</td><td>Salariés, demandeurs d'emploi, reconversion</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-humanitaire-312\">Logement</span></td><td>115, CHRS, SIAO, Fonds FSL, DALO, Action Logement</td><td>Sans-abri, personnes en situation précaire</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-313\">Santé</span></td><td>PASS (Permanences Accès aux Soins), AME, CSS, CPAM</td><td>Personnes sans couverture santé ou en situation précaire</td></tr>\n<tr><td><span class=\"tag tag-red\" data-i18n=\"txt-humanitaire-314\">Juridique</span></td><td>Maisons de justice, aide juridictionnelle, ADIL, DAL</td><td>Personnes sans ressources, locataires, réfugiés</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-humanitaire-315\">Social</span></td><td>France Services (MSAP), Centres sociaux, CCAS, CAF</td><td>Toutes situations, accès aux aides sociales</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-316\">Réfugiés</span></td><td>OFPRA, OFII, CADA, Croix-Rouge, France Terre d'Asile</td><td>Demandeurs d'asile, réfugiés, migrants</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-humanitaire-317\">Alimentation</span></td><td>Banques alimentaires, Restos du Cœur, Secours Catholique</td><td>Personnes en situation de précarité alimentaire</td></tr>\n</tbody>\n</table>",
