    "txt-plateforme-455": "<nav class=\"nav\">\n<a class=\"nav-logo\" data-i18n=\"txt-apropos-158\" href=\"index.html\"><div class=\"logo-icon\">K</div>KIJ<span>.</span></a>\n<div class=\"nav-links\">\n<a data-i18n=\"nav-home\" href=\"index.html\">Accueil</a>\n<a class=\"active\" data-i18n=\"nav-platform\" href=\"plateforme.html\">Plateforme IA</a>\n<a data-i18n=\"nav-aid\" href=\"humanitaire.html\">Aide humanitaire</a>\n<a data-i18n=\"nav-about\" href=\"apropos.html\">À propos</a>\n<a class=\"nav-cta\" data-i18n=\"nav-contact\" href=\"contact.html\">Contact</a>\n<select id=\"lang-select\" style=\"margin-left: 15px; padding: 5px; border-radius: 4px; border: 1px solid var(--border); background: var(--white); color: var(--text);\">\n<option value=\"fr\">FR</option>\n<option value=\"en\">EN</option>\n</select>\n</div>\n<button aria-expanded=\"false\" aria-label=\"Menu\" class=\"hamburger\"><span></span><span></span><span></span></button>\n</nav>\n<nav class=\"mobile-menu\">\n<a data-i18n=\"txt-index-55\" href=\"index.html\">Accueil</a><a data-i18n=\"txt-index-56\" href=\"plateforme.html\">Plateforme IA</a>\n<a data-i18n=\"txt-index-57\" href=\"humanitaire.html\">Aide humanitaire</a><a data-i18n=\"txt-index-58\" href=\"apropos.html\">À propos</a><a data-i18n=\"txt-index-59\" href=\"contact.html\">Contact</a>\n</nav>",
    "txt-plateforme-456": "<a data-i18n=\"nav-home\" href=\"index.html\">Accueil</a>\n<a class=\"active\" data-i18n=\"nav-platform\" href=\"plateforme.html\">Plateforme IA</a>\n<a data-i18n=\"nav-aid\" href=\"humanitaire.html\">Aide humanitaire</a>\n<a data-i18n=\"nav-about\" href=\"apropos.html\">À propos</a>\n<a class=\"nav-cta\" data-i18n=\"nav-contact\" href=\"contact.html\">Contact</a>\n<select id=\"lang-select\" style=\"margin-left: 15px; padding: 5px; border-radius: 4px; border: 1px solid var(--border); background: var(--white); color: var(--text);\">\n<option value=\"fr\">FR</option>\n<option value=\"en\">EN</option>\n</select>",
    "txt-plateforme-457": "<table>\n<thead><tr><th>Couche</th><th>Outil</th><th>Rôle principal</th></tr></thead>\n<tbody>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-plateforme-431\">IA principale</span></td><td><strong data-i18n=\"txt-plateforme-445\">Claude API</strong></td><td>Raisonnement, agents, prompts, rapports, correction linguistique</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-plateforme-432\">Documents</span></td><td><strong data-i18n=\"txt-plateforme-446\">NotebookLM</strong></td><td>Organisation et synthèse de sources documentaires</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-plateforme-433\">Multimodal</span></td><td><strong data-i18n=\"txt-plateforme-447\">Gemini API</strong></td><td>Images, audio, vidéo, documents longs</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-plateforme-434\">Recherche</span></td><td><strong data-i18n=\"txt-plateforme-448\">Perplexity API</strong></td><td>Veille, tendances, sources vérifiées et actualités</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-plateforme-376\">Automatisation</span></td><td><strong data-i18n=\"txt-plateforme-449\">n8n</strong></td><td>Orchestration, webhooks, connexion entre outils</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-index-67\">Base de données</span></td><td><strong data-i18n=\"txt-plateforme-450\">Supabase</strong></td><td>PostgreSQL, auth, stockage fichiers, vecteurs (RAG)</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-index-65\">Agents</span></td><td><strong data-i18n=\"txt-plateforme-451\">CrewAI</strong></td><td>Équipes d'agents spécialisés avec rôles définis</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-plateforme-435\">Orchestration</span></td><td><strong data-i18n=\"txt-plateforme-452\">LangGraph</strong></td><td>Machines à états, routage conditionnel, boucles qualité</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-plateforme-436\">Frontend</span></td><td><strong data-i18n=\"txt-plateforme-453\">React / Next.js</strong></td><td>Interface utilisateur, rendu statique ou serveur</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-plateforme-437\">Backend</span></td><td><strong data-i18n=\"txt-plateforme-454\">Python / FastAPI</strong></td><td>Routes API, logique métier, intégrations</td></tr>\n</tbody>\n</table>",
    "txt-plateforme-458": "<table>\n<thead><tr><th>Table</th><th>Contenu</th></tr></thead>\n<tbody>\n<tr><td><code>users</code></td><td>Comptes, rôles, droits et informations de profil</td></tr>\n<tr><td><code>projects</code></td><td>Objectifs, statut, historique des projets analysés</td></tr>\n<tr><td><code>files</code></td><td>Fichiers déposés, type, catégorie détectée, URL de stockage</td></tr>\n<tr><td><code>agents</code></td><td>Agents disponibles, rôles, prompts, statut actif</td></tr>\n<tr><td><code>skills</code></td><td>Compétences existantes, manquantes et générées</td></tr>\n<tr><td><code>analyses</code></td><td>Résultats, agents utilisés, score de confiance</td></tr>\n<tr><td><code>reports</code></td><td>Rapports finaux, synthèses, recommandations, livrables</td></tr>\n<tr><td><code>sources</code></td><td>Sources officielles, références et vérifications</td></tr>\n<tr><td><code>patents</code></td><td>Brevets connus, mots-clés, similarités</td></tr>\n<tr><td><code>logs</code></td><td>Journal d'exécution, erreurs, tests et événements</td></tr>\n<tr><td><code>workflows</code></td><td>Définitions des flux n8n</td></tr>\n</tbody>\n</table>",
