    "txt-index-119": "<span data-i18n=\"txt-index-52\">© 2026 KIJ Platform — All rights reserved</span>\n<span data-i18n=\"txt-index-53\">Built without external API · <a data-i18n=\"txt-index-74\" href=\"apropos.html#ethics\">Ethics &amp; GDPR</a></span>",
    "txt-apropos-120": "About KIJ",
    "txt-apropos-121": "Vision",
    "txt-apropos-122": "Our values",
    "txt-apropos-123": "Ethical rules",
    "txt-apropos-124": "Questions about the project?",
    "txt-apropos-125": "The central rule",
    "txt-apropos-126": "Clarity",
    "txt-apropos-127": "Kindness",
    "txt-apropos-128": "Rigor",
    "txt-apropos-129": "Complementarity",
    "txt-apropos-130": "Accessibility",
    "txt-apropos-131": "Protection",
    "txt-apropos-132": "A platform built on a simple principle: artificial intelligence must serve all people – professionals or in difficulty.",
    "txt-apropos-133": "KIJ is a multi-agent AI platform designed to make artificial intelligence accessible, useful and ethical — whether to analyze a contract, generate a report, help find a job or direct someone in a crisis situation.",
    "txt-apropos-134": "The platform is based on a conviction: the most powerful tools must be the most accessible. AI should not remain a privilege reserved for large organizations. It must be able to help the person looking for housing, the entrepreneur analyzing their contracts, and the organization generating complex reports.",
    "txt-apropos-135": "When two options are complementary, both are activated. The platform never forces a binary choice between two compatible possibilities.",
    "txt-apropos-136": "Each analysis indicates its confidence level. What is certain, probable, possible or uncertain is always distinguished.",
    "txt-apropos-137": "No situation is judged. The humanitarian module accompanies with dignity, without access conditions and without negative interpretation.",
    "txt-apropos-138": "The platform distinguishes what it can do from what requires a human professional — lawyer, doctor, psychologist.",
    "txt-apropos-139": "The tools are combined, never opposed. Claude, Gemini, Perplexity, n8n and Supabase work together.",
    "txt-apropos-140": "10 languages ​​supported. Language adapted to the level of understanding. FALC available if needed.",
    "txt-apropos-141": "GDPR integrated by design. Anonymized sensitive data. Consent and deletion provided before production.",
    "txt-apropos-142": "Non-negotiable limits that apply to the entire platform.",
    "txt-apropos-143": "The analysis of tone and style remains non-clinical, limited to observable textual signals.",
    "txt-apropos-144": "The platform directs towards probable rights and competent professionals — never towards a decision.",
    "txt-apropos-145": "Each analysis is accompanied by a high / medium / low level with the points to check.",
    "txt-apropos-146": "If a crisis signal is detected, emergency numbers are provided with top priority.",
    "txt-apropos-147": "Confidential files are anonymized before any external processing.",
    "txt-apropos-148": "Official sources (canonical texts, institutions) separated from unofficial sources (hypotheses, oral traditions).",
    "txt-apropos-149": "The goal is to help the person understand and act for themselves.",
    "txt-apropos-150": "The situation, journey and choices of each person are welcomed without negative interpretation.",
    "txt-apropos-151": "We are available to answer any questions about architecture, values ​​or use cases.",
    "txt-apropos-152": "<a href=\"humanitarian.html#emergency\">Emergencies</a>",
    "txt-apropos-153": "<a href=\"about.html\">Values</a>",
    "txt-apropos-154": null,
    "txt-apropos-155": "never “OR”",
