    "txt-contact-214": "<div class=\"feature-item\"><div class=\"feature-dot\"></div><div>Analyze your situation and activate the appropriate agents</div></div>\n<div class=\"feature-item\"><div class=\"feature-dot\"></div><div>Write CV, cover letter, administrative mail</div></div>\n<div class=\"feature-item\"><div class=\"feature-dot\"></div><div>Direct to local resources and associations</div></div>\n<div class=\"feature-item\"><div class=\"feature-dot\"></div><div>Build a concrete and prioritized action plan</div></div>\n<div class=\"feature-item\"><div class=\"feature-dot\"></div><div>Reply in your language</div></div>\n<div class=\"feature-item\"><div class=\"feature-dot\" style=\"background:var(--secondary)\"></div><div style=\"color:var(--text-muted);\">Replace a doctor, lawyer or psychologist — NO</div></div>",
