    "txt-humanitaire-366": "<table>\n<thead>\n<tr><th>Domain</th><th>Structure / Device</th><th>For whom</th></tr>\n</thead>\n<tbody>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-310\">Employment</span></td><td>France Travail (formerly Pôle Emploi), Local Missions, Cap Emploi</td><td>Job seekers, young people, disabled people</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-humanitaire-311\">Training</span></td><td>CPF (My Training Account), OPCO, Pôle Emploi, AFPA</td><td>Employees, job seekers, retraining</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-humanitaire-312\">Housing</span></td><td>115, CHRS, SIAO, FSL Fund, DALO, Action Logement</td><td>Homeless people, people in precarious situations</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-313\">Health</span></td><td>PASS (Permanent Access to Care), AME, CSS, CPAM</td><td>People without health coverage or in a precarious situation</td></tr>\n<tr><td><span class=\"tag tag-red\" data-i18n=\"txt-humanitaire-314\">Legal</span></td><td>Courthouses, legal aid, ADIL, DAL</td><td>People without resources, tenants, refugees</td></tr>\n<tr><td><span class=\"tag tag-green\" data-i18n=\"txt-humanitaire-315\">Social</span></td><td>France Services (MSAP), Social centers, CCAS, CAF</td><td>All situations, access to social assistance</td></tr>\n<tr><td><span class=\"tag tag-blue\" data-i18n=\"txt-humanitaire-316\">Refugees</span></td><td>OFPRA, OFII, CADA, Red Cross, France Terre d'Asile</td><td>Asylum seekers, refugees, migrants</td></tr>\n<tr><td><span class=\"tag tag-orange\" data-i18n=\"txt-humanitaire-317\">Food</span></td><td>Food banks, Restos du Cœur, Secours Catholique</td><td>People experiencing food insecurity</td></tr>\n</tbody>\n</table>",
